      const M = c.month;
      const key = this.n("Line_Key");
      const [ys, ye] = [`\xABV|${this.ys}\xBB`, `\xABV|${this.ye}\xBB`];
      const t = new Table(this, ch, `="${ch.title}: "&${this.n("Line_Label")}&", "&INDEX(List_Years,${this.year})`);
      const asat = `${t.base}/asat`;
      const ids = `${t.base}/ids`;
      const n = 13;
      t.header(["Budget", ...Array.from({ length: 11 }, (_, j) => `=TEXT(INDEX(List_Months,MAX(1,\xABC${J + j + 1}|${asat}\xBB)),"mmm")`), "Current"], "Version");
      const asatCells = {};
      for (let j = 1; j <= 11; j++) asatCells[J + j] = `=\xABV|${this.y0}\xBB-1+${j}`;
      t.rows.push(new LRow(asat, "table", "Reforecast as at month", { indent: 2, role: "r.index", cells: asatCells }));
      const idCells = { [J]: `=IFERROR(INDEX(VR_Id,MATCH("Budget|Approved|"&INDEX(List_Years,${this.year}),VR_BudgetKey,0)),"")` };
      for (let j = 1; j <= 11; j++) {
        const a = `\xABC${J + j}|${asat}\xBB`;
        idCells[J + j] = `=IF(OR(${a}<1,${a}>${M}),"",IFERROR(INDEX(VR_Id,MATCH("Reforecast|"&${a},VR_RefKey,0)),""))`;
      }
