        dir: "col",
        grouping: "stacked",
        gap: 45,
        overlap: 100,
        yFmt: "#,##0",
        legend: "b",
        series: [{ row: rb, as: "bar", colour: "accent1" }, { row: rr, as: "bar", colour: "grey" }, { row: rc, as: "bar", colour: "tx2" }]
