      this.needs("at");
      this.needsVersions(ch);
      const key = this.n("Line_Key");
      const live = `\xABA|${this.lineRow}\xBB`;
      const t = new Table(this, ch, `="${ch.title}: "&${this.n("Line_Label")}&", "&INDEX(List_Years,${this.year})`);
      t.header(this.cats("year"), "Series", "Total");
