      if (pa[0] !== pb[0]) throw new AssemblyError(`rows ${a} and ${b} are on different sheets`);
      const [c0, c1] = kind === "G" ? [FIRST_PERIOD_COL, FIRST_PERIOD_COL + periods - 1] : [Number(c), Number(c)];
      const a1 = `$${colLetter(c0)}$${pa[1]}:$${colLetter(c1)}$${pb[1]}`;
